use verus::prelude::*;

verus! {

    // A small pure helper to state that the concatenation of a Vec<String>
    // is the string you get by folding them together.
    #[verifier(publish)]
    #[verifier::spec]
    fn concat(parts: &Vec<String>) -> String {
        if parts.is_empty() {
            String::new()
        } else {
            let head = parts.get(0).clone();
            let tail = parts.get(1..).to_vec();
            head.clone() + &concat(&tail)
        }
    }

    #[verifier(publish)]
    fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>>
        // the result has the same number of “lines‐lists” as the input had strings
        ensures |res: &Vec<Vec<String>>| res.len() == a.len(),
        // and each sub‐Vec when concatenated equals the original string
        ensures |res: &Vec<Vec<String>>|
            forall(|i: usize| (i < a.len()) ==> concat(&res[i]) == a[i])
    {
        let mut result = Vec::with_capacity(a.len());
        // We iterate one input string s at a time.
        for s in a {
            let bytes = s.as_bytes();
            let len = bytes.len();
            let mut lines: Vec<String> = Vec::new();
            let mut start: usize = 0;
            let mut i: usize = 0;

            // scan s[0..len]
            while i < len
                invariant 0 <= i && i <= len
                invariant 0 <= start && start <= i
                decreases len - i
            {
                let c = bytes[i];
                if c == b'\r' || c == b'\n' {
                    // length of the line ending
                    let newline_len =
                        if c == b'\r' && i + 1 < len && bytes[i + 1] == b'\n' {
                            2
                        } else {
                            1
                        };
                    // end of this slice depends on keepends
                    let end = if keepends {
                        i + newline_len
                    } else {
                        i
                    };
                    // push that slice
                    lines.push(s[start..end].to_string());
                    // advance over the newline
                    i += newline_len;
                    start = i;
                } else {
                    i += 1;
                }
            }

            // any leftover after the last newline
            if start < len {
                lines.push(s[start..len].to_string());
            } else if s.is_empty() {
                // for an empty string we still produce one empty‐string line
                lines.push(String::new());
            }

            result.push(lines);
        }

        result
    }

    // ≔≔≔≔≔≔≔≔≔≔≔≔≔≔≔≔≔≔≔≔≔
    // Tests (these remain pure Rust, Verus will check them too)
    #[cfg(test)]
    mod tests {
        use super::splitlines;

        #[test]
        fn test_basic() {
            let input = vec![
                "Hello\nWorld".to_string(),
                "".to_string(),
                "Foo\r\nBar\rBaz".to_string(),
                "\nLeading newline".to_string(),
                "Trailing newline\n".to_string(),
            ];

            // keepends = false
            let out = splitlines(input.clone(), false);
            assert_eq!(out.len(), input.len());
            assert_eq!(out[0], vec!["Hello".to_string(), "World".to_string()]);
            assert_eq!(out[1], vec!["".to_string()]); // non-empty inner vec
            assert_eq!(out[2], vec!["Foo".to_string(), "Bar".to_string(), "Baz".to_string()]);
            assert_eq!(out[3], vec!["".to_string(), "Leading newline".to_string()]);
            assert_eq!(out[4], vec!["Trailing newline".to_string()]);

            // keepends = true
            let out = splitlines(input, true);
            assert_eq!(out[0], vec!["Hello\n".to_string(), "World".to_string()]);
            assert_eq!(out[1], vec!["".to_string()]);
            assert_eq!(
                out[2],
                vec!["Foo\r\n".to_string(), "Bar\r".to_string(), "Baz".to_string()]
            );
            assert_eq!(out[3], vec!["\n".to_string(), "Leading newline".to_string()]);
            assert_eq!(out[4], vec!["Trailing newline\n".to_string()]);
        }
    }

} // verus!